  ">\n                <option value=\"red\">แดง</option>\n                <option value=\"navy\">กรมท่า</option>\n                <option value=\"gold\">ทอง</option>\n                <option value=\"black\">ดำ</option>\n              </select>\n            </label>\n          </div>\n        </fieldset>\n\n        <fieldset>\n          <legend>หน้าในงานนำเสนอ</legend>\n          <p class=\"sub\">เปลี่ยนหัวข้อ ใส่ภาพ เลือกสินค้าและจำนวนในแต่ละหน้า (สูงสุด 8 รายการเมื่อมีภาพประกอบ, 12 รายการเมื่อไม่มี) · หน้าที่มีสินค้า 1 รายการจะแสดงแบบรายละเอียดพร้อมตารางสเปก</p>\n          <div class=\"pages-bar\">\n            <span class=\"count\" id=\"deck-count\"></span>\n            <label>จัดหน้าอัตโนมัติ หน้าละ <input class=\"num-input\" type=\"number\" name=\"autoPer\" value=\"5\" min=\"1\" max=\"12\"> ชิ้น</label>\n            <button class=\"btn-sm\" type=\"button\" data-act=\"auto-layout\">จัดหน้าใหม่</button>\n            <button class=\"btn-sm\" type=\"button\" data-act=\"add-page\">+ เพิ่มหน้า</button>\n            <button class=\"btn-sm\" type=\"but",
