  "/div>\n          <button class=\"icon-btn\" type=\"button\" data-ed=\"close\" aria-label=\"ปิด\">✕</button>\n        </header>\n        <div class=\"editor-body\">\n          <p class=\"field-label\">รูปสินค้าในงานนำเสนอ</p>\n          <div class=\"img-pick\" id=\"ed-images\"></div>\n          <div class=\"visual-actions\">\n            <label class=\"btn-sm\">อัปโหลดรูปเอง<input class=\"visually-hidden\" type=\"file\" accept=\"image/*\" id=\"ed-upload\"></label>\n          </div>\n          <div class=\"ed-set-only\">\n            <p class=\"field-label ed-members-label\">รายการในชุด <span>แก้ชื่อรุ่น / ขนาด ที่จะแสดงได้</span></p>\n            <div id=\"ed-members\"></div>\n          </div>\n          <div class=\"fields ed-fields\">\n            <label class=\"field field--wide\"><span id=\"ed-name-label\">ชื่อสินค้า *</span><input name=\"ed_name\" required></label>\n            <label class=\"field ed-product-only\"><span>รหัสสินค้า</span><input name=\"ed_sku\"></label>\n            <label class=\"field ed-product-only\"><span>ยี่ห้อ</span><inp",
