  "จาก boonthavorn.com ทุกครั้งที่ค้นหา ราคาและจำนวนสินค้าอาจเปลี่ยนแปลงได้ โปรดตรวจสอบกับหน้าเว็บไซต์ก่อนสั่งซื้อ\n  </footer>\n</div>\n\n<script>\n(() => {\n  'use strict';\n\n  // ---------- Sources ----------\n  const BTV_API = 'https://www.boonthavorn.com/graphql';\n  const BTV_STORE = 'th';\n  const HP_SITE = 'https://www.homepro.co.th/';\n  const WOO_BASE = { traphet: 'https://traphet.com', ecodoor: 'https://www.eco-door.net' };\n  const SOURCES = {\n    btv: { label: 'บุญถาวร', by: 'code' },\n    homepro: { label: 'HomePro', by: 'code' },\n    traphet: { label: 'ตราเพชร', by: 'name' },\n    ecodoor: { label: 'Eco door', by: 'name' },\n    custom: { label: 'ใส่เอง', by: 'none' },\n    mixed: { label: 'หลายแหล่ง', by: 'none' },\n  };\n  const SOURCE_UI = {\n    btv: {\n      label: 'รหัสสินค้าบุญถาวร', placeholder: 'เช่น 1015431',\n      hint: 'ใส่ได้หลายรหัส คั่นด้วยเว้นวรรค จุลภาค หรือขึ้นบรรทัดใหม่ (Shift+Enter) · วางลิงก์หน้าสินค้าก็ได้',\n      examples: [['1015431', '1015431'], ['หลายรหัส', '1015431, ",
  "1068468, 1252051']],\n    },\n    homepro: {\n      label: 'รหัสสินค้า HomePro', placeholder: 'เช่น 1310224',\n      hint: 'รหัสสินค้าจากหน้าสินค้า HomePro ใส่ได้หลายรหัส · วางลิงก์หน้าสินค้าก็ได้',\n      examples: [['1310224', '1310224']],\n    },\n    traphet: {\n      label: 'ชื่อสินค้าตราเพชร', placeholder: 'เช่น ครอบสันโค้ง',\n      hint: 'เว็บนี้ไม่มีรหัสสินค้า ค้นหาด้วยชื่อแทน · ค้นหาหลายชื่อได้โดยขึ้นบรรทัดใหม่ (Shift+Enter) แล้วกด “เพิ่มลงงานนำเสนอ” ที่สินค้าที่ต้องการ',\n      examples: [['ครอบสันโค้ง', 'ครอบสันโค้ง'], ['กระเบื้องลอนคู่', 'กระเบื้องลอนคู่']],\n    },\n    ecodoor: {\n      label: 'ชื่อสินค้า Eco door', placeholder: 'เช่น ประตูไฟเบอร์กลาส',\n      hint: 'เว็บนี้ไม่มีรหัสสินค้า ค้นหาด้วยชื่อแทน · ค้นหาหลายชื่อได้โดยขึ้นบรรทัดใหม่ (Shift+Enter) แล้วกด “เพิ่มลงงานนำเสนอ” ที่สินค้าที่ต้องการ',\n      examples: [['ประตูห้องน้ำ', 'ประตูห้องน้ำ'], ['วงกบ', 'วงกบ']],\n    },\n  };\n  const BTV_CHUNK = 20;\n  const MAX_CODES = 200;\n  const MAX_NAMES = 10;\n  const NAME_RESULTS = 12;\n  //",
  " Attributes already shown elsewhere on the card, or boilerplate on every product.\n  const HIDDEN_ATTRS = new Set(['sku', 'brand', 'remark']);\n\n  const BTV_FIELDS = `items {\n    sku name url_key url_suffix stock_status qty_in_stock ready_to_ship\n    brand_items { title }\n    categories { name url_path }\n    attributes { label value code }\n    media_gallery { url label position disabled }\n    small_image { url }\n    description { html }\n    price_range { minimum_price {\n      final_price { value currency }\n      regular_price { value }\n      discount { percent_off amount_off }\n    } }\n  }`;\n  const btvQuery = (field) =>\n    `query ($v: [String]) { products(filter: { ${field}: { in: $v } }, pageSize: ${BTV_CHUNK}) { ${BTV_FIELDS} } }`.replace(/\\s+/g, ' ');\n  const BTV_BY_SKU = btvQuery('sku');\n  const BTV_BY_KEY = btvQuery('url_key');\n\n  const $ = (sel) => document.querySelector(sel);\n  const form = $('#search-form');\n  const input = $('#codes');\n  const submitBtn = $('#submit');\n  const ",
  "statusEl = $('#status');\n  const toolbar = $('#toolbar');\n  const summaryEl = $('#summary');\n  const resultsEl = $('#results');\n  const exportBtn = $('#export');\n  const toDeckBtn = $('#to-deck');\n  const connEl = $('#conn');\n  const sourceNoteEl = $('#source-note');\n  const proxyInput = $('#proxy-input');\n\n  let currentSource = 'btv';\n  let lastGroups = [];               // [{ query, views }] from the latest search\n  const viewsByKey = new Map();      // every product seen this session, for the add buttons\n  let requestId = 0;\n\n  const esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) =>\n    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n  const numFmt = new Intl.NumberFormat('th-TH', { minimumFractionDigits: 0, maximumFractionDigits: 2 });\n  const satangFmt = new Intl.NumberFormat('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n  const money = (v) => (v == null ? '-' : Number.isInteger(v) ? numFmt.format(v) : satangFmt.format(v));\n",
  "  const priceText = (v) => `${v.priceFrom ? 'เริ่มต้น ' : ''}${money(v.final)} บาท${v.unit ? ' / ' + v.unit : ''}`;\n\n  function plainText(html) {\n    const doc = new DOMParser().parseFromString('<div>' + String(html ?? '') + '</div>', 'text/html');\n    return (doc.body.textContent || '').replace(/\\s+/g, ' ').trim();\n  }\n\n  // ---------- Helper / proxy ----------\n  // HomePro pages, ตราเพชร's store API and the WordPress images don't allow cross-site reads,\n  // so those go through a helper on the same address as the page: start.bat on this computer\n  // (\"local\") or the online system on Cloudflare (\"cloud\"), or a proxy URL the user sets.\n  const PROXY_KEY = 'btv-proxy-v1';\n  const SAME_ORIGIN_PROXY = /^https?:$/.test(location.protocol) ? location.origin + '/proxy?url=' : '';\n  let proxyBase = '';\n  let proxyKind = 'none';\n\n  async function initProxy() {\n    let custom = '';\n    try { custom = localStorage.getItem(PROXY_KEY) || ''; } catch (_) { custom = ''; }\n    proxyInput.value = cust",
