  " name + '.pptx';\n  }\n\n  // Pages holding more items than their layout fits continue on extra slides;\n  // `start` is the number before the slide's first item.\n  function expandPages(list, starts) {\n    const out = [];\n    for (const p of list) {\n      const max = maxFor(p);\n      const base = (starts.get(p.id) || { start: 0 }).start;\n      for (let i = 0; i < Math.max(p.keys.length, 1); i += max) {\n        out.push({ ...p, keys: p.keys.slice(i, i + max), start: base + i, note: i ? '' : p.note });\n      }\n    }\n    return out;\n  }\n\n  async function generateDeck() {\n    const used = pages.filter((p) => p.keys.length || p.image || (p.note || '').trim());\n    if (!used.length) {\n      showDeckNote('bad', 'ยังไม่มีหน้าที่มีเนื้อหา เพิ่มสินค้าหรือรูปในหน้าก่อน');\n      return;\n    }\n    deckBtn.disabled = true;\n    deckBtn.textContent = 'กำลังสร้างไฟล์…';\n    try {\n      showDeckNote('info', 'กำลังโหลดเครื่องมือสร้างไฟล์…');\n      const PptxGenJS = await loadPptx();\n      const keys = [...ne",
