  "531;\n      --accent: #4fbfa5; --accent-soft: #17322c; --accent-ink: #0b1f1a;\n      --ok: #74d18f; --warn: #f0c060; --warn-soft: #3a2d12; --bad: #f29482; --bad-soft: #3a1d18;\n      --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 6px 20px rgba(0, 0, 0, .25);\n      color-scheme: dark;\n    }\n  }\n  * { box-sizing: border-box; }\n  body { margin: 0; background: var(--bg); color: var(--text); font-family: \"IBM Plex Sans Thai\", \"Leelawadee UI\", Tahoma, system-ui, sans-serif; font-size: 17px; line-height: 1.7; }\n  .wrap { max-width: 820px; margin: 0 auto; padding: 0 16px 56px; }\n  header { padding: 40px 0 8px; }\n  .eyebrow { margin: 0 0 6px; font-size: .8rem; font-weight: 600; color: var(--accent); }\n  h1 { margin: 0; font-size: clamp(1.5rem, 4vw, 2rem); line-height: 1.3; }\n  .lede { margin: 10px 0 0; color: var(--muted); }\n  nav.toc { margin: 24px 0 8px; padding: 16px 20px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); }\n  nav.toc p { margin: 0 0 6px; font-",
